def ttl_cache(function, maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    cache = {}
    hits = misses = 0
    def decorated(*args, **kwargs):
        nonlocal hits, misses
        key = (args, frozenset(kwargs.items())) if typed else args
        now = timer()
        if key in cache:
            _, ttl_left, item = cache[key]
            if now - ttl_left >= 0:
                misses += 1
                del cache[key]
            else:
                hits += 1
        else:
            misses += 1
        if misses > maxsize:
            cache.popitem(last=False)
        cache[key] = (now, ttl_left + ttl, function(*args, **kwargs))
        return cache[key][2]
    decorated.cache_info = lambda: {"hits": hits, "misses": misses, "maxsize": maxsize, "ttl": ttl}
    return decorated

