def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if path.endswith('0=*'):
        return 'root'
    elif path.endswith('0=z'):
        return 'object'
    else:
        try:
            with open(path, 'r') as f:
                return 'file' if f.read().startswith('namaste') else 'other'
        except OSError:
            return f'cannot open {path} for reading'
        except UnicodeDecodeError:
            return f'cannot decode {path} as UTF-8'

def find_path_type(path):
    try:
        with open(path, "rb") as f:
            magic_bytes = f.read(4)
            if magic_bytes[:2] == b"PK":
                return "zip"
            elif magic_bytes[:3] == b"Ocfl":
                return "object"
            else:
                return "file"
    except FileNotFoundError as e:
        return "directory"

